import {
  assertCan,
  CashMovement,
  LocalDate,
  Money,
  NotFound,
  type PaymentMethod,
} from '@cashpilot/domain';
import { type Actor } from '../shared/actor';
import { type Deps } from '../shared/deps';
import { attempt, matchesQuery, ok, paginate, type Page, type Result } from '../shared/result';
import { invoiceAuditView } from '../invoices/invoice-dto';

export interface RecordPaymentInput {
  invoiceId: string;
  amountMillimes: number;
  date: string;
  method: PaymentMethod;
  /**
   * Idempotency key generated by the form. A retried submit with the same key is a no-op,
   * and the ledger's unique (sourceType, sourceId) makes a double append impossible anyway.
   */
  operationId?: string;
}

/** Payment + IN ledger movement + audit entry, in one transaction. */
export class RecordPayment {
  constructor(private readonly deps: Deps) {}

  async execute(actor: Actor, input: RecordPaymentInput): Promise<Result<{ paymentId: string; remainingMillimes: number }>> {
    const { clock, ids } = this.deps;
    return attempt(() =>
      this.deps.uow.run(async (tx) => {
        assertCan(actor, 'payment.record');
        const invoice = await tx.invoices.byId(actor.companyId, input.invoiceId);
        if (!invoice) throw new NotFound();
        if (input.operationId && invoice.hasPayment(input.operationId)) {
          return ok({ paymentId: input.operationId, remainingMillimes: invoice.remaining().millimes });
        }
        const company = await tx.companies.byId(actor.companyId);
        if (!company) throw new NotFound();
        const before = invoiceAuditView(invoice);
        const payment = invoice.recordPayment({
          paymentId: input.operationId ?? ids.next(),
          amount: Money.ofMillimes(input.amountMillimes),
          date: LocalDate.parse(input.date),
          method: input.method,
          today: clock.today(),
          createdById: actor.userId,
        });
        await tx.invoices.save(invoice);
        await tx.ledger.append(
          CashMovement.fromPayment(ids.next(), actor.companyId, payment, `Encaissement ${invoice.number}`, company.openingDate),
        );
        await tx.audit.record({
          companyId: actor.companyId,
          actorId: actor.userId,
          action: 'payment.recorded',
          entityType: 'Invoice',
          entityId: invoice.id,
          before,
          after: { ...invoiceAuditView(invoice), paymentId: payment.id, amountMillimes: payment.amount.millimes, date: payment.date.toString() },
        });
        return ok({ paymentId: payment.id, remainingMillimes: invoice.remaining().millimes });
      }),
    );
  }
}

/** Counter-entry (never an update): reversal payment + OUT movement + audit. */
export class ReversePayment {
  constructor(private readonly deps: Deps) {}

  async execute(
    actor: Actor,
    input: { invoiceId: string; paymentId: string; reason: string; date?: string },
  ): Promise<Result<{ reversalId: string }>> {
    const { clock, ids } = this.deps;
    return attempt(() =>
      this.deps.uow.run(async (tx) => {
        assertCan(actor, 'payment.reverse');
        const invoice = await tx.invoices.byId(actor.companyId, input.invoiceId);
        if (!invoice) throw new NotFound();
        const company = await tx.companies.byId(actor.companyId);
        if (!company) throw new NotFound();
        const before = invoiceAuditView(invoice);
        const reversal = invoice.reversePayment({
          reversalId: ids.next(),
          paymentId: input.paymentId,
          reason: input.reason,
          date: input.date ? LocalDate.parse(input.date) : clock.today(),
          createdById: actor.userId,
        });
        await tx.invoices.save(invoice);
        await tx.ledger.append(
          CashMovement.fromPayment(ids.next(), actor.companyId, reversal, `Contre-passation ${invoice.number}`, company.openingDate),
        );
        await tx.audit.record({
          companyId: actor.companyId,
          actorId: actor.userId,
          action: 'payment.reversed',
          entityType: 'Invoice',
          entityId: invoice.id,
          before,
          after: { ...invoiceAuditView(invoice), reversalId: reversal.id, reversesId: input.paymentId, reason: reversal.reason },
        });
        return ok({ reversalId: reversal.id });
      }),
    );
  }
}

export interface PaymentListRow {
  id: string;
  invoiceId: string;
  invoiceNumber: string;
  clientName: string;
  date: string;
  amountMillimes: number;
  method: PaymentMethod;
  isReversal: boolean;
  reversed: boolean;
  reason: string | null;
}

export interface ListPaymentsInput {
  from?: string;
  to?: string;
  q?: string;
  page?: number;
}

export class ListPayments {
  constructor(private readonly deps: Deps) {}

  async execute(actor: Actor, input: ListPaymentsInput = {}): Promise<Result<Page<PaymentListRow> & { totalMillimes: number }>> {
    return attempt(() =>
      this.deps.uow.read(async (r) => {
        assertCan(actor, 'invoice.read');
        const [invoices, clients] = await Promise.all([
          r.invoices.list(actor.companyId, { statuses: ['ISSUED', 'CANCELLED'] }),
          r.parties.list(actor.companyId, { kind: 'CLIENT', includeArchived: true }),
        ]);
        const names = new Map(clients.map((c) => [c.id, c.name]));
        const rows: PaymentListRow[] = invoices
          .flatMap((inv) =>
            inv.payments.map((p) => ({
              id: p.id,
              invoiceId: inv.id,
              invoiceNumber: inv.number ?? '—',
              clientName: names.get(inv.clientId) ?? '—',
              date: p.date.toString(),
              amountMillimes: p.amount.millimes,
              method: p.method,
              isReversal: p.isReversal,
              reversed: inv.isReversed(p.id),
              reason: p.reason,
            })),
          )
          .filter((p) => (!input.from || p.date >= input.from) && (!input.to || p.date <= input.to))
          .filter((p) => matchesQuery(input.q, p.invoiceNumber, p.clientName))
          .sort((a, b) => b.date.localeCompare(a.date) || a.id.localeCompare(b.id));
        const total = rows.reduce((s, p) => s + (p.isReversal ? -p.amountMillimes : p.amountMillimes), 0);
        return ok({ ...paginate(rows, input.page), totalMillimes: total });
      }),
    );
  }
}
